const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const pacificPalisades = ee.Geometry.Point([-118.5255, 34.0340]); // Pacific Palisades, CA

  const date1 = '2025-01-09';
  const date2 = '2025-01-12';

  const bandName = 'tropospheric_NO2_column_number_density';
  const scale = 1113.2; // Approximate resolution of S5P NO2 is 5.5 x 3.5 km, using ~1km for reducer scale

  // 2. Data Acquisition & Check
  const s5p = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .filterBounds(pacificPalisades)
    .select(bandName)
    .filter(ee.Filter.gt('qa_value', 0.75)); // Filter for good quality data

  const collection1 = s5p.filterDate(date1, ee.Date(date1).advance(1, 'day'));
  const collection2 = s5p.filterDate(date2, ee.Date(date2).advance(1, 'day'));

  const count1 = collection1.size().getInfo();
  const count2 = collection2.size().getInfo();

  if (count1 === 0 || count2 === 0) {
    console.log(`Images for ${date1}: ${count1}`);
    console.log(`Images for ${date2}: ${count2}`);
    console.log("C1: Empty Collection (No images found for one or both dates after QA filter).");
    return;
  }

  // Get the first image for each date (assuming daily data is sufficient)
  const image1 = collection1.first();
  const image2 = collection2.first();

  // 3. Processing & Calculation
  const reducer = ee.Reducer.mean();

  // Reduce region for date 1
  const mean1 = image1.reduceRegion({
    reducer: reducer,
    geometry: pacificPalisades,
    scale: scale,
    maxPixels: 1e9
  }).get(bandName);

  // Reduce region for date 2
  const mean2 = image2.reduceRegion({
    reducer: reducer,
    geometry: pacificPalisades,
    scale: scale,
    maxPixels: 1e9
  }).get(bandName);

  let val1, val2;
  try {
    val1 = await ee.data.computeValue(mean1);
    val2 = await ee.data.computeValue(mean2);
  } catch (error) {
    console.log("C3: Calculation Failure - Could not compute mean values.");
    return;
  }

  // Check for C3 (Calculation Failure - None, NaN)
  if (val1 === null || isNaN(val1) || val2 === null || isNaN(val2)) {
    console.log(`NO2 on ${date1}: ${val1}`);
    console.log(`NO2 on ${date2}: ${val2}`);
    console.log("C3: Calculation Failure (Result is None or NaN for one or both dates).");
    return;
  }

  // Convert from mol/m^2 to µmol/m^2 for better readability (multiply by 1e6)
  const val1_micromol = val1 * 1e6;
  const val2_micromol = val2 * 1e6;

  // 4. Validation & Final Answer
  console.log(`Images for ${date1}: ${count1}`);
  console.log(`Images for ${date2}: ${count2}`);
  console.log(`Mean tropospheric NO2 on ${date1}: ${val1_micromol.toFixed(4)} µmol/m²`);
  console.log(`Mean tropospheric NO2 on ${date2}: ${val2_micromol.toFixed(4)} µmol/m²`);

  if (val1_micromol > val2_micromol) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
